#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
INSTALADOR - Primer Examen Parcial (pagina del sindicato)
=========================================================
En el proyecto sindicato-sesion1 crea/actualiza:
  src/data/examen-primer-parcial.js         (30 reactivos | clave 1306 | timer 90s | orden fijo)
  src/app/examen/primer-parcial/page.js     (pagina del examen, resultados al final)
Y agrega la tarjeta "Primer Examen Parcial" en src/app/page.js (array EXAMENES),
SIN mostrar la clave en el subtitulo. Si ya estaba con la clave visible, la limpia.

Seguro: respaldo automatico, idempotente, solo toca esos archivos.
Ejecutar desde la raiz del proyecto:
    cd ~/Desktop/sindicato-sesion1
    python3 instalar_primer_parcial.py
"""
import os, sys, base64, json, shutil
from datetime import datetime

PAYLOAD_B64 = ""

ROOT = os.getcwd()
TS = datetime.now().strftime("%Y%m%d_%H%M%S")
BACKUP_DIR = os.path.join(ROOT, "_backups_primer_parcial_" + TS)

HOME = os.path.join(ROOT, "src", "app", "page.js")
DATA_OUT = os.path.join(ROOT, "src", "data", "examen-primer-parcial.js")
PAGE_OUT = os.path.join(ROOT, "src", "app", "examen", "primer-parcial", "page.js")

ANCHOR = "const EXAMENES = ["
CARD_GUARD = 'id: "primer-parcial"'
CLAVE_VISIBLE = "Educaci\u00f3n Especial + Horas Adicionales \u00b7 clave 1306"
CLAVE_LIMPIA = "Educaci\u00f3n Especial + Horas Adicionales"

def die(m):
    print("\n[ERROR] " + m); sys.exit(1)

def backup(abs_path):
    if os.path.isfile(abs_path):
        rel = os.path.relpath(abs_path, ROOT)
        dst = os.path.join(BACKUP_DIR, rel)
        os.makedirs(os.path.dirname(dst), exist_ok=True)
        shutil.copy2(abs_path, dst)
        return True
    return False

def write_file(abs_path, content):
    existed = backup(abs_path)
    os.makedirs(os.path.dirname(abs_path), exist_ok=True)
    with open(abs_path, "w", encoding="utf-8") as f:
        f.write(content)
    rel = os.path.relpath(abs_path, ROOT)
    print(("   [~] actualizado " if existed else "   [+] creado     ") + rel)

def main():
    print("=" * 60)
    print("  INSTALADOR - Primer Examen Parcial (clave 1306, oculta)")
    print("  SNTE / sindicato-sesion1")
    print("=" * 60)

    if not os.path.isfile(HOME) or not os.path.isdir(os.path.join(ROOT, "src", "data")):
        die("No parece la raiz de sindicato-sesion1.\n"
            "   Entra a la carpeta:  cd ~/Desktop/sindicato-sesion1\n"
            "   (debe existir src/app/page.js y src/data/)")

    data = json.loads(base64.b64decode(PAYLOAD_B64).decode())
    data_js = base64.b64decode(data["data_b64"]).decode()
    page_js = base64.b64decode(data["page_b64"]).decode()
    card    = base64.b64decode(data["card_b64"]).decode()

    print("\nProyecto: " + ROOT)
    print("Backups : " + os.path.relpath(BACKUP_DIR, ROOT) + "/  (solo si algo existia)\n")

    print("Escribiendo archivos:")
    write_file(DATA_OUT, data_js)
    write_file(PAGE_OUT, page_js)

    print("\nEnlazando tarjeta en el home (src/app/page.js):")
    with open(HOME, "r", encoding="utf-8") as f:
        content = f.read()
    original = content

    if CARD_GUARD in content:
        print("   [=] La tarjeta 'Primer Examen Parcial' ya existe")
    elif ANCHOR in content:
        content = content.replace(ANCHOR, ANCHOR + card, 1)
        print("   [~] Tarjeta agregada al array EXAMENES (sin clave visible)")
    else:
        print("   [!] No encontre 'const EXAMENES = [' en src/app/page.js.")
        print("       La pagina y los datos quedaron creados; agrega la tarjeta a mano si hace falta.")

    # Limpieza: si quedo la clave visible de una corrida anterior, quitarla
    if CLAVE_VISIBLE in content:
        content = content.replace(CLAVE_VISIBLE, CLAVE_LIMPIA)
        print("   [~] Quitada la clave visible del subtitulo de la tarjeta")

    if content != original:
        backup(HOME)
        with open(HOME, "w", encoding="utf-8") as f:
            f.write(content)
    else:
        print("   [=] src/app/page.js sin cambios")

    print("\n" + "=" * 60)
    print("LISTO. Ruta del examen (clave 1306, ya NO visible):")
    print("   /examen/primer-parcial")
    print("\nVerifica y publica:")
    print("   npm run build")
    print("   git add src/data/examen-primer-parcial.js \\")
    print("           src/app/examen/primer-parcial/page.js \\")
    print("           src/app/page.js")
    print('   git commit -m "Primer Examen Parcial (30 reactivos, clave 1306 oculta, timer 90s)"')
    print("   git push")
    print("=" * 60)

if __name__ == "__main__":
    main()
